    this.discount = 0; // percent, 0-100
  }

  addItem(name, price, qty = 1) {
    if (typeof price !== "number" || price < 0) {
      throw new Error("price must be a non-negative number");
    }
    if (!Number.isInteger(qty) || qty < 1) {
      throw new Error("qty must be a positive integer");
    }
    this.items.push({ name, price, qty });
  }

  setDiscount(percent) {
    if (percent < 0 || percent > 100) {
      throw new Error("discount must be between 0 and 100");
    }
    this.discount = percent;
  }

  // BUG: subtotal is wrong — it ignores qty entirely.
  subtotal() {
    let sum = 0;
    for (const it of this.items) {
      sum += it.price;
    }
    return sum;
  }

  // BUG: total applies the discount in the wrong direction
  // (a 10% discount should remove 10%, not add it).
  total() {
    const sub = this.subtotal();
    return sub + (sub * this.discount) / 100;
  }

  // BUG: this should merge duplicate items with the same name into one
  // entry with combined qty, but it returns empty array when no duplicates
  // exist (it should return the items unchanged in that case).
  mergeDuplicates() {
    const seen = new Map();
    const out = [];
    for (const it of this.items) {
      if (seen.has(it.name)) {
        const idx = seen.get(it.name);
        out[idx] = { ...it, qty: out[idx].qty + it.qty };
      } else {
        seen.set(it.name, out.length);
        out.push(it);
      }
    }
    return out.length === this.items.length ? [] : out;
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { Cart } from "../lib/cart.js";

test("subtotal multiplies price by qty", () => {
  const c = new Cart();
  c.addItem("apple", 0.5, 4);
  c.addItem("pear", 1.2, 2);
  assert.equal(c.subtotal(), 0.5 * 4 + 1.2 * 2);
});

test("subtotal handles single item with qty 1", () => {
  const c = new Cart();
  c.addItem("pen", 3.0);
  assert.equal(c.subtotal(), 3.0);
});

test("total applies discount by subtracting", () => {
  const c = new Cart();
  c.addItem("book", 40, 1);
  c.addItem("mag", 10, 3);
  c.setDiscount(10);
  assert.equal(c.total(), (40 + 30) * 0.9);
});

test("zero discount leaves total unchanged", () => {
  const c = new Cart();
  c.addItem("book", 50, 1);
  assert.equal(c.total(), 50);
});

test("mergeDuplicates keeps unique items unchanged", () => {
  const c = new Cart();
  c.addItem("a", 1, 1);
  c.addItem("b", 2, 1);
  const merged = c.mergeDuplicates();
  assert.equal(merged.length, 2);
  assert.deepEqual(merged[0], { name: "a", price: 1, qty: 1 });
});

test("mergeDuplicates combines same-name items", () => {
  const c = new Cart();
  c.addItem("a", 1, 1);
  c.addItem("a", 1, 2);
  const merged = c.mergeDuplicates();
  assert.equal(merged.length, 1);
  assert.equal(merged[0].qty, 3);
});

